#!/bin/sh
# Regenerate the customized Montserrat fonts. Reproducible replacement for
# the manual fontforge procedure in README.md:
#  - Montserrat-Medium-v9.ttf: stock Montserrat (has the Bitcoin sign 0x20BF
#    natively, plus the general-punctuation block 0x2013-0x2026)
#  - SatoshiSymbol.ttf: 2-glyph donor font for the satoshi symbols
#    0x4E2F (italic) / 0x4E30 (regular), built to match Montserrat Medium
#    metrics (see README.md)
# Run from anywhere; requires node + lv_font_conv (npx fetches it) and the
# FontAwesome woff from lvgl/scripts/built_in_font/.
set -e
SRC="$(cd "$(dirname "$0")" && pwd)"
cd "$SRC/../lib/lvgl/scripts/built_in_font"
# Stage the custom fonts here so the generated .c files embed bare
# filenames (matching the original convention), not local paths.
cp "$SRC/Montserrat-Medium-v9.ttf" "$SRC/SatoshiSymbol.ttf" .

echo "Generating lv_font_montserrat_10.c"
npx lv_font_conv --no-compress --no-prefilter --bpp 4 --size 10 --font Montserrat-Medium-v9.ttf -r 0x20-0xFF,0xB0,0x2013-0x2014,0x2018-0x2019,0x201C-0x201D,0x2022,0x2026,0x20BF --font SatoshiSymbol.ttf -r 0x4E2F,0x4E30 --font FontAwesome5-Solid+Brands+Regular.woff -r 61441,61448,61451,61452,61452,61453,61457,61459,61461,61465,61468,61473,61478,61479,61480,61502,61507,61512,61515,61516,61517,61521,61522,61523,61524,61543,61544,61550,61552,61553,61556,61559,61560,61561,61563,61587,61589,61636,61637,61639,61641,61664,61671,61674,61683,61724,61732,61787,61931,62016,62017,62018,62019,62020,62087,62099,62212,62189,62810,63426,63650,0xf002,0xf004,0xf005,0xf00e,0xf010,0xf029,0xf030,0xf15a,0xf164,0xf165,0xf1e0,0xf2ea,0xf379,0xf58f --format lvgl -o "$SRC/lv_font_montserrat_10.c" --force-fast-kern-format
